/*
 * A154777  Numbers of the form x^2 + 2*y^2 with positive integers x and y.
 * https://oeis.org/A154777
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = smallest n terms of the set {x^2 + 2*y^2 | x,y ≥ 1},
 *            sorted in increasing order
 * Range:     u8 n <= 93, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by a min‑heap frontier. A process for each
   fixed x generates the increasing list of values with that x.  To keep
   the heap size linear the algorithm only adds a new x when its first
   element is no larger than the current minimum in the heap. */

/* ----------------------------------------------------------------- */

#include <stdlib.h>

typedef struct {
    idx_t x;
    idx_t y;
    seq_t val;
} node_t;

static seq_t *sequence = NULL;      /* stored sequence values          */
static size_t seq_len  = 0;
static size_t seq_cap  = 0;

static node_t *heap = NULL;         /* min‑heap of frontier nodes     */
static size_t heap_len = 0;
static size_t heap_cap = 0;

static idx_t next_x = 1;            /* smallest x not yet inserted    */

/* ----------------------------------------------------------------- */
/* min‑heap helpers                                                   */
static void swap_node(node_t *a, node_t *b)
{
    node_t tmp = *a;
    *a = *b;
    *b = tmp;
}

static void heap_grow(void)
{
    heap_cap = heap_cap ? heap_cap * 2U : 16U;
    node_t *tmp = (node_t *)realloc(heap, heap_cap * sizeof(node_t));
    if (!tmp) abort();
    heap = tmp;
}

static void heap_push(idx_t x, idx_t y, seq_t val)
{
    if (heap_len == heap_cap) heap_grow();
    size_t i = heap_len++;
    heap[i].x   = x;
    heap[i].y   = y;
    heap[i].val = val;
    /* sift up */
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p].val <= heap[i].val) break;
        swap_node(&heap[p], &heap[i]);
        i = p;
    }
}

static node_t heap_pop(void)
{
    node_t res = heap[0];
    heap[0] = heap[--heap_len];
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1;
        size_t r = l + 1;
        size_t smallest = i;
        if (l < heap_len && heap[l].val < heap[smallest].val) smallest = l;
        if (r < heap_len && heap[r].val < heap[smallest].val) smallest = r;
        if (smallest == i) break;
        swap_node(&heap[i], &heap[smallest]);
        i = smallest;
    }
    return res;
}

/* ----------------------------------------------------------------- */
/* sequence generation                                                 */
static void ensure_n_terms(idx_t n)
{
    if (seq_len == 0) {
        /* (re‑)initialise for a brand‑new sequence */
        next_x = 1;
        heap_len = 0;
    }

    while (seq_len < n) {

        /* Insert new x’s while their first element does not exceed the
           current minimum in the heap.  When the heap is empty we insert
           the next x automatically.                                        */
        seq_t cand = (seq_t)next_x * (seq_t)next_x + (seq_t)2U;
        if (heap_len == 0 || cand <= heap[0].val) {
            heap_push(next_x, 1U, cand);
            ++next_x;
            continue;
        }

        /* Extract the smallest value from the heap. */
        node_t cur = heap_pop();

        /* Store the value if it is new (duplicate elimination). */
        if (seq_len == 0 || cur.val != sequence[seq_len - 1]) {
            if (seq_len == seq_cap) {
                seq_cap = seq_cap ? seq_cap * 2U : 16U;
                seq_t *tmp = (seq_t *)realloc(sequence, seq_cap * sizeof(seq_t));
                if (!tmp) abort();
                sequence = tmp;
            }
            sequence[seq_len++] = cur.val;
        }

        /* Push the next y value for the same x. */
        idx_t y_next = cur.y + 1U;
        seq_t val_next = (seq_t)cur.x * (seq_t)cur.x
                         + (seq_t)2U * (seq_t)y_next * (seq_t)y_next;
        heap_push(cur.x, y_next, val_next);
    }
}

/* ----------------------------------------------------------------- */
/* public API                                                          */
seq_t a(idx_t n)
{
    if (n == 0U) return (seq_t)0;   /* undefined for offset 1 */
    ensure_n_terms(n);
    return sequence[n - 1U];
}
